#!/usr/bin/env python3
"""
Mega random-coefficient adaptive JAX-Fourier benchmark.

Purpose
-------
This is the large-dimensional stress test version.

It runs the adaptive JAX-Fourier bounce solver for nphi = 1 ... 50 on the same
random-coefficient potential family that is also exported to Mathematica.

Potential
---------
For each nphi:

    V(phi) = (sum_i c_i (phi_i - 1)^2 - delta) * sum_i phi_i^2

The coefficients c_i and delta are fixed deterministic numbers generated with
seed 20260508. For nphi=N, the coefficient vector uses the first N entries of
a master list. This makes the N-field case a nested extension of the smaller
cases.

The false vacuum is at phi = 0. The true vacuum is found numerically.

Path ansatz
-----------
Fourier endpoint-safe path:

    phi_i(t) = phi_false_i + t(phi_true_i - phi_false_i)
               + sum_k a_{i,k} sin(k*pi*t)

Adaptive stopping
-----------------
The solver does NOT need a reference action.

For each n_modes:
    1. compile JAX action/gradient once for this mode
    2. run selected starts
    3. keep the minimum action at this mode
    4. update global best action
    5. stop if global best does not improve by TOLERANCE for PATIENCE mode steps

Outputs
-------
    mega_random_jax_history.csv
    mega_random_jax_summary.csv

Install
-------
    python3 -m pip install "jax[cpu]" scipy pandas numpy

Run
---
    python3 mega_random_jax_fourier.py
"""

import time
import json
from dataclasses import dataclass
from typing import Optional

import numpy as np
import pandas as pd
from scipy.optimize import minimize

import jax
jax.config.update("jax_enable_x64", True)
import jax.numpy as jnp


# ============================================================
# User settings
# ============================================================

NPHI_VALUES = list(range(1, 51))

N_START = 3
N_MAX = 25
N_STEP = 1

TOLERANCE = 1.0e-3
PATIENCE = 3

N_GRID = 260
MAXITER = 800
GTOL = 1e-7
FTOL = 1e-10

USE_ZERO_START = True
USE_PREVIOUS_WARM_START = True
USE_BEST_WARM_START = False
N_RANDOM_STARTS = 0
RANDOM_SCALE = 0.03

BOUND_FACTOR = 0.5

HISTORY_CSV = "mega_random_jax_history.csv"
SUMMARY_CSV = "mega_random_jax_summary.csv"


